const TIME_LIMIT: int = 3292;
const OPENING_BUFFER: int = 120;

// Each spawned task retains one handle, including older stripes of the same id.
// Source funcSet3 adds F0/F1 to *living* laser origins, not just new offsets.
async sub moving_stripe(x: fx, y: fx, a: angle, length: fx, id: int) {
    // Source 1282/1328: initialLength=0, targetLength=rank value,
    // speed=6, width=16, flags=2 (full segment). Approved constant-width
    // Line approximation: target collision width=8, L>16 after two ticks.
    var h: int = laser(2, x, y, a, 0fx, 8fx, 2, 65535, 0);
    if h >= 0 {
        lz_speed(h, 6fx, length);
        // No age cutoff: source OFFSCREEN(250) is not a 250-frame lifetime.
        // Target keeps offscreen stripes until its flying-rod exit condition;
        // near>640 is already beyond the entire 384px horizontal playfield.
        while lz_alive(h) == 1 {
            if self_int(0) == 1 {
                lz_cancel(h);
                return;
            }
            lz_origin(h, lz_x(h), lz_y(h) + self_fx(id));
            wait(1);
        }
    }
}

// Synchronous scheduler preserves source async at / synchronous at2 relationship:
// at: 0..150,160..310; at2: 10..160,170..320; next pair starts at330.
// Creation tasks add one common target frame to both groups, no relative skew.
sub stripes() {
    var length: fx = 300fx;
    if global(GVAR_RANK) == 1 { length = 600fx; }
    if global(GVAR_RANK) == 2 { length = 650fx; }
    if global(GVAR_RANK) == 3 { length = 700fx; }
    var y0: fx = 0fx;
    var y1: fx = 0fx;
    var a0: angle = 0deg;
    var a1: angle = 180deg;
    var x0: fx = -192fx;
    var x1: fx = 192fx;
    var t: int = 0;
    var b: int = -1;
    var unused_a: int = 2;
    // Source C=1000; actual spell interrupt ends the task before exhaustion.
    for cycle in 0..1000 {
        b = b + 1;
        if b >= 2 { unused_a = 3; }
        for tick in 0..330 {
            // Separate source RANDF reads at 1287,1297,1333,1343.
            // The sample at tick160 is at's second sample before at2's old
            // stripe; no RNG is consumed by the per-laser mover tasks.
            if tick == 0 {
                y0 = 448fx - (rand(10000) as fx / 10000fx) * 20fx;
                x0 = -192fx;
                a0 = 0deg;
            }
            if tick == 10 {
                y1 = (rand(10000) as fx / 10000fx) * 20fx;
                x1 = 192fx;
                a1 = 180deg;
            }
            if tick == 160 {
                y0 = 448fx - (rand(10000) as fx / 10000fx) * 20fx;
                x0 = 192fx;
                a0 = 180deg;
            }
            if tick == 170 {
                y1 = (rand(10000) as fx / 10000fx) * 20fx;
                x1 = -192fx;
                a1 = 0deg;
            }
            if tick % 10 == 0 && tick < 320 {
                spawn moving_stripe(x0, y0, a0, length, 0);
                y0 = y0 - 64fx;
            }
            if tick >= 10 && tick % 10 == 0 {
                spawn moving_stripe(x1, y1, a1, length, 1);
                y1 = y1 + 64fx;
            }
            wait(1);
            t = t + 1;
            // Source reset is at BossCard4 frame4, firing begins at94:
            // 90 frames already elapsed, leaving2910 until Boss5 interrupt.
            if t >= 2910 { return; }
        }
    }
    loop { wait(1000); }
}

async sub source_boss() {
    // Boss context 10-29, Boss4 lifeSet3001. No pre-card callback/async
    // survives the entry cleanup. Source circular boxes are diameters.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    // Boss4 495-499: preserve both +2 waits; chapter/presentation omitted.
    wait(2);
    wait(2);
    // 501-516 reset/kill/clear/funcSet0/laserCancel precede motion.
    // Fresh independent owner has no children/lasers to cancel here.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    // movePosTime(0,...) only cancels interpolation; no teleport to(0,0).
    // Both known limits contain this monotone path, so no clamp is reached.
    move_to(160, 0fx, 144fx, EASE_QUAD_IN_OUT);
    wait(160);
    // BossCard4 1201-1227, same ordered cleanup and four explicit frames.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(2);
    wait(2);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    // Source spell timer begins here (entry+168); 1234 mode4, limit
    // center(0,128), size(240,64), again never reached by this move.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);
    // Only this reachable owner installs funcSet3; BossCard4_en is absent.
    set_self_fx(0, 0.5fx);
    set_self_fx(1, -0.5fx);
    stripes();
    set_self_int(0, 1);
    wait(1); // Let each handle owner apply laserCancel before retirement.
    // Source Boss5 starts at timer3000 and cancels lasers/async. Owner
    // retirement cancels its mover task tree; control ends the segment next.
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3001, 0, 0, 0, source_boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
